import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

public class KeepAliveClientTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /**
     * Serves exactly one connection: every line comes back uppercased with a "!"
     * until the client sends QUIT. Returns { replies, linesTheServerSaw, connections }.
     */
    static String[] round(List<String> requests) {
        ServerSocket server = null;
        Thread serverThread = null;
        final List<String> seen = Collections.synchronizedList(new ArrayList<String>());
        final int[] connections = new int[1];
        String replies;
        try {
            server = new ServerSocket(0, 4, InetAddress.getByName("127.0.0.1"));
            final ServerSocket listening = server;
            serverThread = new Thread(() -> {
                Socket peer = null;
                try {
                    listening.setSoTimeout(700);
                    peer = listening.accept();
                    connections[0]++;
                    peer.setSoTimeout(2000);
                    BufferedReader in = new BufferedReader(new InputStreamReader(
                            peer.getInputStream(), StandardCharsets.UTF_8));
                    BufferedWriter out = new BufferedWriter(new OutputStreamWriter(
                            peer.getOutputStream(), StandardCharsets.UTF_8));
                    String line;
                    while ((line = in.readLine()) != null) {
                        seen.add(line);
                        if (line.equals("QUIT")) {
                            break;
                        }
                        out.write(line.toUpperCase(Locale.ROOT) + "!");
                        out.write("\n");
                        out.flush();
                    }
                } catch (Exception ignored) {
                    // the checks below report whatever the client managed to get
                } finally {
                    if (peer != null) {
                        try {
                            peer.close();
                        } catch (IOException ignored) {
                            // nothing useful to do
                        }
                    }
                }
            });
            serverThread.setDaemon(true);
            serverThread.start();

            List<String> got = KeepAliveClient.ask("127.0.0.1", server.getLocalPort(), requests);
            replies = got == null ? "null" : got.toString();
        } catch (Exception e) {
            replies = "failed: " + e.getClass().getSimpleName();
        } finally {
            if (serverThread != null) {
                try {
                    serverThread.join(4000);
                } catch (InterruptedException ignored) {
                    Thread.currentThread().interrupt();
                }
            }
            if (server != null) {
                try {
                    server.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
        }
        return new String[] { replies, seen.toString(), String.valueOf(connections[0]) };
    }

    public static void main(String[] args) {
        String[] three = round(Arrays.asList("a", "b", "c"));
        check("three requests, three replies, in order", "[A!, B!, C!]", three[0]);
        check("the server saw every request plus QUIT", "[a, b, c, QUIT]", three[1]);
        check("only ONE connection was opened", "1", three[2]);

        String[] one = round(Arrays.asList("hello sockets"));
        check("a single request", "[HELLO SOCKETS!]", one[0]);
        check("a single request is still followed by QUIT", "[hello sockets, QUIT]", one[1]);

        String[] none = round(new ArrayList<String>());
        check("no requests means no replies", "[]", none[0]);
        check("but the connection is still opened and closed politely", "[QUIT]", none[1]);
        check("an empty conversation still uses one connection", "1", none[2]);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
        System.exit(0);
    }
}

