import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * TASK: Talk to a server over ONE reused connection instead of reconnecting.
 *
 * ask(host, port, requests) must:
 *   1. open a SINGLE Socket to host:port (use a 2000 ms connect timeout and
 *      socket.setSoTimeout(2000) so a silent server cannot hang you),
 *   2. for EACH request: write the request followed by "\n", FLUSH, then read
 *      exactly one reply line and add it to the result list,
 *   3. after the last request, send the line "QUIT" (and flush) to tell the
 *      server you are done,
 *   4. close the socket and return the replies, in request order.
 *
 * The whole conversation happens on that one socket -- opening a new Socket
 * per request is exactly what this exercise is asking you NOT to do.
 * If a reply line is missing (the server closed early), add "<no reply>" for it.
 *
 * Example: ask("127.0.0.1", port, List.of("a", "b")) against a shouting server
 *          -> ["A!", "B!"], and the server saw the lines a, b, QUIT.
 * An empty request list still connects and still sends QUIT, returning [].
 */
public class KeepAliveClient {

    public static List<String> ask(String host, int port, List<String> requests) throws IOException {
        List<String> replies = new ArrayList<>();
        Socket socket = new Socket();
        try {
            socket.connect(new InetSocketAddress(InetAddress.getByName(host), port), 2000);
            socket.setSoTimeout(2000);
            BufferedWriter out = new BufferedWriter(
                    new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
            BufferedReader in = new BufferedReader(
                    new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));

            for (String request : requests) {
                out.write(request);
                out.write("\n");
                out.flush();
                String reply = in.readLine();
                replies.add(reply == null ? "<no reply>" : reply);
            }

            out.write("QUIT");
            out.write("\n");
            out.flush();
        } finally {
            socket.close();
        }
        return replies;
    }
}
